// =====================================================================
// EVERWAKE CLINIC — Test Runner · NODE: Read Test Command
// Chat with a clinic's assistant as a pretend patient. The real Main
// workflow answers; nothing is sent on WhatsApp.
//
//   any text                 a patient's message
//   /reset   (ريست)          forget the test chat: a brand-new patient
//   /last    (آخر)           show the latest turn again, sending nothing
//   /later 5 <message>       5 hours pass first, then the message
//   #2 <message>             a second pretend patient (#1 … #99)
//   @slug <message>          another clinic, by its slug
// =====================================================================
const CLINIC = 'nile_clinics';     // the slug of the clinic to test
const NAME = 'تجربة';

let raw = String($input.first().json.chatInput ?? '').trim();
let clinicSlug = CLINIC, n = 1, m;
if ((m = raw.match(/^@(\S+)\s*([\s\S]*)$/))) { clinicSlug = m[1]; raw = m[2].trim(); }
if ((m = raw.match(/^#(\d{1,2})\s*([\s\S]*)$/))) { n = Math.min(Math.max(Number(m[1]), 1), 99); raw = m[2].trim(); }
const later = raw.match(/^\/(?:later|بعد)\s+(\d+(?:\.\d+)?)\s*([\s\S]*)$/i);
if (later) raw = later[2].trim();
const reset = /^\/?(reset|ريست)$/i.test(raw);
const last = /^\/(last|آخر)$/i.test(raw);
return [{ json: { restaurant: clinicSlug, clinic: clinicSlug, wa_id: '2000000000' + String(n).padStart(2, '0'),
                  push_name: NAME + (n > 1 ? ' ' + n : ''), text: reset || last ? '' : raw, location: null, reset, last,
                  later_hours: later ? Number(later[1]) : 0, empty: !reset && !last && !raw } }];

// =====================================================================
// EVERWAKE CLINIC — Test Runner · NODE: Fake WhatsApp Message
// The message as Evolution would deliver it, plus test_run: Main then
// records its replies instead of sending them.
// =====================================================================
const cmd = $('Read Test Command').first().json;
const r = $input.first().json.r;
const message = cmd.location
  ? { locationMessage: { degreesLatitude: cmd.location.lat, degreesLongitude: cmd.location.lng, name: cmd.text || undefined } }
  : { conversation: cmd.text };
return [{
  json: {
    test_run: true,
    query: { token: r.token },
    body: {
      event: 'messages.upsert',
      instance: r.instance,
      data: {
        key: { remoteJid: `${r.wa_id}@s.whatsapp.net`, fromMe: false, id: 'TESTIN' + Date.now() + Math.random().toString(36).slice(2, 8) },
        pushName: cmd.push_name,
        messageType: cmd.location ? 'locationMessage' : 'conversation',
        messageTimestamp: Math.floor(Date.now() / 1000),
        message
      }
    }
  }
}];

// =====================================================================
// EVERWAKE CLINIC — Test Runner · NODE: Format Test Result
// The reply exactly as the patient would get it, then what the assistant did.
// =====================================================================
const cmd = $('Read Test Command').first().json;
const prep = $('Prepare Test Chat').first().json.r || {};
const res = ($input.first().json.r) || {};
const short = (v, n = 600) => { const s = typeof v === 'string' ? v : JSON.stringify(v); return !s ? '' : s.length > n ? s.slice(0, n - 1) + '…' : s; };
if (cmd.empty) return [{ json: { output: 'Type a patient message, or /reset, /last, /later 5 <message>.' } }];
if (prep.reset) return [{ json: { output: `RESET — ${prep.clinic}: the test chat ${prep.wa_id} starts from zero (a brand-new patient).` } }];
const replies = Array.isArray(res.replies) ? res.replies : [];
const said = replies.map(m => m.kind === 'text' ? m.text : `[${m.kind}] ${m.text || ''}`).join('\n[[NEXT]]\n');
const t = res.turn || {};
const b = t.plan && typeof t.plan === 'object' ? t.plan : null;
const lines = [
  `${cmd.last ? '(the latest turn again) ' : ''}${prep.later_hours ? `(${prep.later_hours} hours later) ` : ''}PATIENT: ${res.patient ?? cmd.text}`,
  `ASSISTANT: ${said || '(no reply — see the Main execution)'}`,
  '',
  `${prep.clinic} · ${prep.status}${res.mode === 'human' ? ' · A PERSON TOOK OVER' : ''}${res.urgency ? ' · FLAGGED ' + res.urgency.toUpperCase() : ''} · stage=${t.stage ?? '-'} · ${t.seconds ?? '-'}s · ${t.tokens ?? '-'} tokens`,
  ...((t.calls || []).map(c => `→ ${c.tool} ${short(c.asked, 220)} ⇒ ${c.status || '?'}${c.error ? ' «' + c.error + '»' : ''}${(c.problems || []).length ? ' ' + c.problems.join(',') : ''}`)),
  (t.caught || []).length ? `caught=${short(t.caught, 800)}${t.rewritten ? ' → repaired' : ''}` : 'caught=none',
  b && b.used ? `plan: ${b.stage} — ${b.objective}\n  move: ${b.move}\n  urgency: ${JSON.stringify(b.urgency || {})}` : `plan=${b ? '(none: ' + b.error + ')' : '-'}`,
  res.draft ? `booking in progress=${short(res.draft, 400)}` : '',
  res.appointments ? `appointments=${short(res.appointments, 500)}` : '',
  t.booked ? `BOOKED ${t.booked}` : '',
  t.handoff && t.handoff.needed ? `HANDOFF: ${t.handoff.reason}` : '',
  t.ask_team && t.ask_team.length ? `ASKED THE DOCTOR: ${[].concat(t.ask_team).join(' | ')}` : ''
].filter(l => l !== '');
return [{ json: { output: lines.join('\n'), reply: said || null } }];
